// Results.jsx  –  Screen 5: Report Results Screen
// Renders the full report object generated by Generate.jsx (hearingRiskEngine.js),
// following the structure of Recommended_Report_Format.docx.
//
// PDF export uses react-native-html-to-pdf + react-native-share — these are
// native modules for BARE React Native (not Expo Go). Install with:
//   npm install react-native-html-to-pdf react-native-share
//   cd ios && pod install
// Android autolinking picks both up automatically on the next native rebuild.
import React, { useState } from 'react';
import {
  View, Text, TouchableOpacity, ScrollView,
  StatusBar, SafeAreaView, Alert, ActivityIndicator,
} from 'react-native';
import RNHTMLtoPDF from 'react-native-html-to-pdf';
import Share from 'react-native-share';
import { buildReportHtml } from '../utils/reportHtml'; 

// ── Risk classification → color mapping (shared visual language with home.jsx) ──
const RISK_COLORS = {
  LOW: { color: '#22C55E', bg: '#F0FDF4', icon: '✅' },
  MODERATE: { color: '#F59E0B', bg: '#FFFBEB', icon: '⚠️' },
  HIGH: { color: '#EF4444', bg: '#FEF2F2', icon: '🔴' },
  CRITICAL: { color: '#7C3AED', bg: '#F5F3FF', icon: '🚨' },
};

const getRiskStyle = (classification) => RISK_COLORS[classification] || RISK_COLORS.MODERATE;

// Human-readable labels for the medical risk factors object produced by
// evaluateMedicalRisk() in hearingRiskEngine.js — keep in sync with that file.
const FACTOR_LABELS = {
  hearingDifficulty: 'Self-reported hearing difficulty',
  asymmetricHearing: 'Asymmetric hearing (one ear worse)',
  earPain: 'Ear pain (last 6 months)',
  occupationalNoiseExposure: 'Occupational noise exposure',
  inconsistentProtection: 'Inconsistent hearing protection use',
  neverUsesProtection: 'Never uses hearing protection',
  longTermExposure: 'Long-term exposure (5+ years)',
  veryLongTermExposure: 'Very long-term exposure (10+ years)',
  noPriorHearingTest: 'No previous hearing test',
  familyHistory: 'Family history of hearing loss',
};

const formatDate = (isoString) => {
  if (!isoString) return '—';
  const d = new Date(isoString);
  return d.toLocaleDateString('en-US', { day: '2-digit', month: 'long', year: 'numeric' });
};

const formatTime = (isoString) => {
  if (!isoString) return '—';
  const d = new Date(isoString);
  return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
};

const ResultsScreen = ({ navigation, route }) => {
  const { report } = route.params || {};
  const [isExporting, setIsExporting] = useState(false);

  // ── Download PDF ──
  // 1. Build the report's HTML representation (reportHtml.js).
  // 2. Render it to a real PDF file on-device via react-native-html-to-pdf.
  // 3. Hand that file to react-native-share, which opens the native
  //    save/share sheet (and correctly handles Android's FileProvider
  //    requirements, unlike sharing a raw file:// URI directly).
  const handleDownloadPdf = async () => {
    if (!report || isExporting) return;
    setIsExporting(true);
    try {
      const html = buildReportHtml(report);

      const pdf = await RNHTMLtoPDF.convert({
        html,
        fileName: report.reportId || `HearingReport_${Date.now()}`,
        base64: false,
      });

      await Share.open({
        url: `file://${pdf.filePath}`,
        type: 'application/pdf',
        title: 'Hearing Screening Report',
        failOnCancel: false, // user dismissing the share sheet isn't an error
      });
    } catch (err) {
      // react-native-share throws when the user cancels the sheet on some
      // platforms even with failOnCancel — filter that out from real errors.
      if (err?.message !== 'User did not share') {
        console.error('Failed to generate/share PDF:', err);
        Alert.alert('Download Failed', 'Could not generate the PDF. Please try again.');
      }
    } finally {
      setIsExporting(false);
    }
  };

  if (!report) {
    return (
      <SafeAreaView style={{ flex: 1, backgroundColor: '#F8FAFC', alignItems: 'center', justifyContent: 'center', padding: 24 }}>
        <Text style={{ fontSize: 40, marginBottom: 12 }}>📄</Text>
        <Text style={{ fontSize: 17, fontWeight: '800', color: '#1E293B', textAlign: 'center' }}>
          No Report Data Found
        </Text>
        <Text style={{ fontSize: 13, color: '#64748B', textAlign: 'center', marginTop: 6, marginBottom: 20 }}>
          Please complete a hearing test to generate a report.
        </Text>
        <TouchableOpacity
          onPress={() => navigation.navigate('Home')}
          style={{ backgroundColor: '#1A3C6E', borderRadius: 12, paddingVertical: 12, paddingHorizontal: 24 }}
        >
          <Text style={{ color: '#FFFFFF', fontWeight: '700' }}>Back to Home</Text>
        </TouchableOpacity>
      </SafeAreaView>
    );
  }

  const {
    reportId, testDate,
    userInfo, medicalHistorySummary, frequencyTable,
    earSummary, hearingPerformance, medicalRisk, finalRisk,
    recommendations, disclaimer,
  } = report;

  const finalStyle = getRiskStyle(finalRisk.classification);

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: '#F8FAFC' }}>
      <StatusBar barStyle="light-content" backgroundColor="#1A3C6E" />

      {/* ── Header ── */}
      <View style={{
        backgroundColor: '#1A3C6E',
        paddingTop: 50, paddingBottom: 20, paddingHorizontal: 20,
        alignItems: 'center',
        borderBottomWidth: 1,
        borderBottomColor: 'rgba(255,255,255,0.08)',
      }}>
        <Text style={{ color: '#A8C4E0', fontSize: 12, fontWeight: '500', letterSpacing: 0.4, textAlign: 'center' }}>
          HEARING SCREENING REPORT
        </Text>
        <Text style={{ color: '#FFFFFF', fontSize: 19, fontWeight: '700', letterSpacing: 0.3, marginTop: 4, textAlign: 'center' }}>
          Report #{reportId}
        </Text>
      </View>

      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={{ paddingHorizontal: 16, paddingTop: 20, paddingBottom: 24, gap: 18 }}
        showsVerticalScrollIndicator={false}
      >

        {/* ── Final Risk Banner (headline result) ── */}
        <View style={{
          borderRadius: 18, padding: 20,
          backgroundColor: finalStyle.bg,
          borderWidth: 1, borderColor: finalStyle.color + '30',
          alignItems: 'center', gap: 8,
        }}>
          <Text style={{ fontSize: 34 }}>{finalStyle.icon}</Text>
          <Text style={{ fontSize: 12, color: '#64748B', fontWeight: '600', letterSpacing: 0.5 }}>
            FINAL RISK CLASSIFICATION
          </Text>
          <Text style={{ fontSize: 24, fontWeight: '800', color: finalStyle.color }}>
            {finalRisk.classification} RISK
          </Text>
          <Text style={{ fontSize: 13, color: '#475569', textAlign: 'center', lineHeight: 19, marginTop: 4 }}>
            {finalRisk.explanation}
          </Text>
          {finalRisk.specialistReferral && (
            <View style={{
              marginTop: 8, backgroundColor: finalStyle.color, borderRadius: 10,
              paddingVertical: 8, paddingHorizontal: 14,
            }}>
              <Text style={{ color: '#FFFFFF', fontSize: 12, fontWeight: '700' }}>
                ⚕ Specialist Referral Recommended
              </Text>
            </View>
          )}
        </View>

        {/* ── Section 1: User Information ── */}
        <Section title="Section 1 — User Information">
          <Card>
            <InfoRow label="Report ID" value={reportId} />
            <InfoRow label="Test Date" value={formatDate(testDate)} />
            <InfoRow label="Test Time" value={formatTime(testDate)} />
            <Divider />
            <InfoRow label="Name" value={userInfo.name || '—'} />
            <InfoRow label="Age" value={userInfo.age || '—'} />
            <InfoRow label="Gender" value={userInfo.gender || '—'} />
            <InfoRow label="Occupation" value={userInfo.occupation || '—'} />
            <InfoRow label="Phone Number" value={userInfo.phoneNumber || '—'} />
            <InfoRow label="Email" value={userInfo.email || '—'} />
            <InfoRow label="Employee ID" value={userInfo.employeeId || '—'} last />
          </Card>
        </Section>

        {/* ── Section 2: Medical History Summary ── */}
        <Section title="Section 2 — Medical History Summary">
          <Card>
            {medicalHistorySummary.map((item, index) => (
              <View
                key={item.questionId}
                style={{
                  paddingVertical: 10,
                  borderTopWidth: index === 0 ? 0 : 1,
                  borderTopColor: '#F1F5F9',
                }}
              >
                <Text style={{ fontSize: 12.5, color: '#374151', lineHeight: 18 }}>{item.question}</Text>
                <Text style={{ fontSize: 13, fontWeight: '700', color: '#1A3C6E', marginTop: 3 }}>
                  {item.answer}
                </Text>
              </View>
            ))}
          </Card>
        </Section>

        {/* ── Section 3: Hearing Screening Results ── */}
        <Section title="Section 3 — Hearing Screening Results">
          <Card noPad>
            <View style={{ flexDirection: 'row', backgroundColor: '#F8FAFC', paddingVertical: 10, paddingHorizontal: 12 }}>
              <HeaderCell flex={1.2} text="Frequency (Hz)" />
              <HeaderCell flex={1} text="Left Ear" />
              <HeaderCell flex={1} text="Right Ear" />
            </View>
            {frequencyTable.map((row, index) => (
              <View
                key={row.frequency}
                style={{
                  flexDirection: 'row', alignItems: 'center',
                  paddingVertical: 9, paddingHorizontal: 12,
                  borderTopWidth: 1, borderTopColor: '#F1F5F9',
                  backgroundColor: index % 2 === 0 ? '#FFFFFF' : '#FAFBFC',
                }}
              >
                <Text style={{ flex: 1.2, fontSize: 12.5, color: '#1E293B', fontWeight: '600' }}>
                  {row.frequency}
                </Text>
                <StatusCell flex={1} status={row.left} />
                <StatusCell flex={1} status={row.right} />
              </View>
            ))}
          </Card>
        </Section>

        {/* ── Section 4: Frequency Response Summary ── */}
        <Section title="Section 4 — Frequency Response Summary">
          <View style={{ flexDirection: 'row', gap: 12 }}>
            <EarSummaryCard label="Left Ear" summary={earSummary.left} />
            <EarSummaryCard label="Right Ear" summary={earSummary.right} />
          </View>
        </Section>

        {/* ── Section 5: Hearing Performance Analysis ── */}
        <Section title="Section 5 — Hearing Performance Analysis">
          <View style={{ flexDirection: 'row', gap: 12 }}>
            <ScoreCard label="Left Ear" score={hearingPerformance.leftScore} category={hearingPerformance.leftCategory} />
            <ScoreCard label="Right Ear" score={hearingPerformance.rightScore} category={hearingPerformance.rightCategory} />
          </View>
          <View style={{ marginTop: 12 }}>
            <ScoreCard
              label="Overall Hearing Performance"
              score={hearingPerformance.overallScore}
              category={hearingPerformance.overallCategory}
              wide
            />
          </View>
        </Section>

        {/* ── Section 6: Medical Risk Analysis ── */}
        <Section title="Section 6 — Medical Risk Analysis">
          <Card>
            <RiskBadge classification={medicalRisk.classification} label="Medical Risk Classification" />
            <Text style={{ fontSize: 12, fontWeight: '700', color: '#64748B', marginTop: 16, marginBottom: 8, letterSpacing: 0.3 }}>
              RISK FACTOR SUMMARY
            </Text>
            {Object.entries(medicalRisk.factors).map(([key, present]) => (
              <FactorRow key={key} label={FACTOR_LABELS[key] || key} present={present} />
            ))}
          </Card>
        </Section>

        {/* ── Section 7: Final Risk Evaluation ── */}
        <Section title="Section 7 — Final Risk Evaluation">
          <Card>
            <RiskBadge classification={finalRisk.classification} label="Final Classification" />
            <Text style={{ fontSize: 13, color: '#374151', lineHeight: 20, marginTop: 14 }}>
              {finalRisk.explanation}
            </Text>
          </Card>
        </Section>

        {/* ── Section 8/9: Personalized Recommendations ── */}
        <Section title="Section 8 — Personalized Recommendations">
          <Card>
            {recommendations.map((rec, index) => (
              <View
                key={index}
                style={{
                  flexDirection: 'row', gap: 10, alignItems: 'flex-start',
                  paddingVertical: 8,
                  borderTopWidth: index === 0 ? 0 : 1,
                  borderTopColor: '#F1F5F9',
                }}
              >
                <Text style={{ fontSize: 14, color: '#1A3C6E', marginTop: 1 }}>•</Text>
                <Text style={{ flex: 1, fontSize: 13, color: '#374151', lineHeight: 19 }}>{rec}</Text>
              </View>
            ))}
          </Card>
        </Section>

        {/* ── Section 11: Disclaimer ── */}
        <View style={{
          backgroundColor: '#F1F5F9', borderRadius: 12, padding: 14,
        }}>
          <Text style={{ fontSize: 11, color: '#64748B', lineHeight: 16, fontStyle: 'italic', textAlign: 'center' }}>
            {disclaimer}
          </Text>
        </View>

      </ScrollView>

      {/* ── Bottom Action Bar ── */}
      <View style={{
        paddingHorizontal: 16, paddingBottom: 30, paddingTop: 12,
        backgroundColor: '#F8FAFC',
        borderTopWidth: 1, borderTopColor: '#E2E8F0',
        flexDirection: 'row', gap: 12,
      }}>
        <TouchableOpacity
          onPress={handleDownloadPdf}
          disabled={isExporting}
          activeOpacity={0.75}
          style={{
            flex: 1,
            borderRadius: 14, paddingVertical: 15,
            alignItems: 'center', justifyContent: 'center',
            flexDirection: 'row', gap: 8,
            backgroundColor: '#FFFFFF',
            borderWidth: 1.5, borderColor: '#CBD5E1',
            opacity: isExporting ? 0.7 : 1,
          }}
        >
          {isExporting ? (
            <ActivityIndicator size="small" color="#1A3C6E" />
          ) : (
            <Text style={{ fontSize: 16 }}>⬇️</Text>
          )}
          <Text style={{ color: '#1A3C6E', fontSize: 15, fontWeight: '700' }}>
            {isExporting ? 'Preparing…' : 'Download PDF'}
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          onPress={() => navigation.navigate('Home')}
          activeOpacity={0.85}
          style={{
            flex: 1,
            borderRadius: 14, paddingVertical: 15,
            alignItems: 'center', justifyContent: 'center',
            backgroundColor: '#1A3C6E',
            shadowColor: '#1A3C6E',
            shadowOffset: { width: 0, height: 6 },
            shadowOpacity: 0.35, shadowRadius: 10, elevation: 8,
          }}
        >
          <Text style={{ color: '#FFFFFF', fontSize: 15, fontWeight: '700', letterSpacing: 0.4 }}>
            Back to Dashboard
          </Text>
        </TouchableOpacity>
      </View>

    </SafeAreaView>
  );
};

/* ─────────────────────────── Sub-components ─────────────────────────── */

const Section = ({ title, children }) => (
  <View style={{ gap: 10 }}>
    <Text style={{ fontSize: 15, fontWeight: '800', color: '#1E293B', letterSpacing: 0.1 }}>
      {title}
    </Text>
    {children}
  </View>
);

const Card = ({ children, noPad = false }) => (
  <View style={{
    backgroundColor: '#FFFFFF',
    borderRadius: 14,
    padding: noPad ? 0 : 16,
    overflow: 'hidden',
    shadowColor: '#000', shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05, shadowRadius: 6, elevation: 2,
  }}>
    {children}
  </View>
);

const Divider = () => <View style={{ height: 1, backgroundColor: '#F1F5F9', marginVertical: 8 }} />;

const InfoRow = ({ label, value, last = false }) => (
  <View style={{
    flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center',
    paddingVertical: 6,
  }}>
    <Text style={{ fontSize: 12.5, color: '#64748B' }}>{label}</Text>
    <Text style={{ fontSize: 13, fontWeight: '700', color: '#1E293B' }}>{value}</Text>
  </View>
);

const HeaderCell = ({ flex, text }) => (
  <Text style={{ flex, fontSize: 11, fontWeight: '700', color: '#64748B', letterSpacing: 0.3 }}>
    {text}
  </Text>
);

const StatusCell = ({ flex, status }) => {
  const isHeard = status === 'Heard';
  return (
    <View style={{ flex, flexDirection: 'row', alignItems: 'center', gap: 5 }}>
      <View style={{
        width: 7, height: 7, borderRadius: 3.5,
        backgroundColor: isHeard ? '#22C55E' : '#EF4444',
      }} />
      <Text style={{
        fontSize: 12, fontWeight: '600',
        color: isHeard ? '#22C55E' : '#EF4444',
      }}>
        {status}
      </Text>
    </View>
  );
};

const EarSummaryCard = ({ label, summary }) => (
  <View style={{
    flex: 1, backgroundColor: '#FFFFFF', borderRadius: 14, padding: 14,
    shadowColor: '#000', shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05, shadowRadius: 6, elevation: 2, gap: 8,
  }}>
    <Text style={{ fontSize: 13, fontWeight: '800', color: '#1E293B' }}>{label}</Text>

    <View>
      <Text style={{ fontSize: 10.5, color: '#94A3B8', fontWeight: '600' }}>HEARD FREQUENCIES</Text>
      <Text style={{ fontSize: 11.5, color: '#22C55E', fontWeight: '600', marginTop: 2, lineHeight: 16 }}>
        {summary.heardFrequencies.length ? summary.heardFrequencies.join(', ') : 'None'}
      </Text>
    </View>

    <View>
      <Text style={{ fontSize: 10.5, color: '#94A3B8', fontWeight: '600' }}>MISSED FREQUENCIES</Text>
      <Text style={{ fontSize: 11.5, color: '#EF4444', fontWeight: '600', marginTop: 2, lineHeight: 16 }}>
        {summary.missedFrequencies.length ? summary.missedFrequencies.join(', ') : 'None'}
      </Text>
    </View>

    <Divider />

    <InfoRow label="Highest Audible" value={summary.highestAudibleFrequency ? `${summary.highestAudibleFrequency} Hz` : '—'} />
    <InfoRow label="Lowest Audible" value={summary.lowestAudibleFrequency ? `${summary.lowestAudibleFrequency} Hz` : '—'} last />
  </View>
);

const ScoreCard = ({ label, score, category, wide = false }) => (
  <View style={{
    flex: wide ? undefined : 1,
    width: wide ? '100%' : undefined,
    backgroundColor: '#FFFFFF', borderRadius: 14, padding: 16,
    shadowColor: '#000', shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05, shadowRadius: 6, elevation: 2,
    alignItems: wide ? 'center' : 'flex-start', gap: 4,
  }}>
    <Text style={{ fontSize: 11.5, color: '#64748B', fontWeight: '600' }}>{label}</Text>
    <Text style={{ fontSize: 26, fontWeight: '800', color: '#1A3C6E' }}>{score}%</Text>
    <Text style={{
      fontSize: 11, fontWeight: '600', color: '#475569',
      textAlign: wide ? 'center' : 'left',
    }}>
      {category}
    </Text>
  </View>
);

const RiskBadge = ({ classification, label }) => {
  const style = getRiskStyle(classification);
  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
      <View style={{
        width: 46, height: 46, borderRadius: 23,
        backgroundColor: style.bg, alignItems: 'center', justifyContent: 'center',
      }}>
        <Text style={{ fontSize: 22 }}>{style.icon}</Text>
      </View>
      <View>
        <Text style={{ fontSize: 11.5, color: '#64748B', fontWeight: '600' }}>{label}</Text>
        <Text style={{ fontSize: 18, fontWeight: '800', color: style.color }}>{classification}</Text>
      </View>
    </View>
  );
};

const FactorRow = ({ label, present }) => (
  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 5 }}>
    <Text style={{
      fontSize: 14, fontWeight: '800',
      color: present ? '#22C55E' : '#CBD5E1',
    }}>
      {present ? '✓' : '✗'}
    </Text>
    <Text style={{
      fontSize: 12.5,
      color: present ? '#1E293B' : '#94A3B8',
      fontWeight: present ? '600' : '400',
    }}>
      {label}
    </Text>
  </View>
);

export default ResultsScreen;